/**
 * Topics whose every case matches real kotlinc: `npm run test:topic-coverage` replays the stored kotlinc outputs
 * (expected.json, written by `npm run audit:topic-coverage -- --write-expected`) for exactly these topics.
 */
export const DONE_TOPICS = ['strings', 'chars', 'numbers', 'ranges', 'decisions', 'arrays', 'lists', 'sets', 'maps', 'collectionsTyped', 'nulls', 'exceptions', 'builders', 'functions', 'classes'];

/** Cases that differ from kotlinc ON PURPOSE, with the reason. Everything else in a DONE topic must match. */
export const KNOWN_LIMITS: Record<string, string> = {
  'val s = StringBuilder("abc")\nprintln(s[1])': 'Indexing a StringBuilder with [] is not translated (use s.get(1) or s.toString()[1]).',
  'try { listOf(1)[3] } catch (e: Exception) { println(e.message) }': 'The JDK message of a one-element immutable list differs ("Index: 3, Size: 1"); other lists say "Index 3 out of bounds for length N".',
  "println('a'.compareTo('c'))": 'A Char and a one-letter String are the same JS string, so Char.compareTo (-1/0/1) cannot be told from String.compareTo (the difference).',
  "println('a'.plus(2))": 'Char.plus(Int) would need the receiver typed as Char; String.plus(Any) concatenates. Use `\'a\' + 2`, which is typed statically.',
  'println(Long.MAX_VALUE)': 'A Long is a JavaScript number here (exact only up to 2^53); Long.MAX_VALUE is reported as unsupported instead of printing a wrong value.',
};
